#include <bits/stdc++.h>
using namespace std;
struct E {int from,to,a; vector<int> in,out;};
struct N {int p; vector<int> r; int parent,edge; bool live;};
int main(int ac,char**av){ifstream f(av[1]);int d,np,ne,ni,ng;f>>d>>np>>ne>>ni>>ng;assert(f&&d>=1);vector<char>initial(np);for(int i=0,p;i<ni;i++){f>>p;initial.at(p)=1;}vector<pair<int,vector<int>>>goals;for(int j=0,p;j<ng;j++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals.push_back({p,r});}vector<E>es;vector<vector<int>>inc(np);for(int i=0;i<ne;i++){E e;f>>e.from>>e.to>>e.a;e.in.resize(d);e.out.resize(d);for(auto&x:e.in)f>>x;for(auto&x:e.out)f>>x;assert(f);inc[e.to].push_back(i);es.push_back(e);}uint64_t limit=ac>2?stoull(av[2]):1000000;vector<N>nodes;vector<vector<int>>basis(np);uint64_t comparisons=0,retired=0;int hit=-1;auto le=[&](const vector<int>&a,const vector<int>&b){comparisons++;for(int i=0;i<d;i++)if(a[i]>b[i])return false;return true;};auto add=[&](int p,const vector<int>&r,int par,int edge){auto&v=basis[p];for(int id:v)if(nodes[id].live&&le(nodes[id].r,r))return;for(int id:v)if(nodes[id].live&&le(r,nodes[id].r)){nodes[id].live=false;retired++;}if(v.size()>32){vector<int>w;for(int id:v)if(nodes[id].live)w.push_back(id);v.swap(w);}int id=nodes.size();nodes.push_back({p,r,par,edge,true});v.push_back(id);if(initial[p]&&all_of(r.begin(),r.end(),[](int x){return x==0;}))hit=id;};for(auto&[p,r]:goals)add(p,r,-1,-1);size_t next=nodes.size();int depth=0;
for(size_t k=0;k<nodes.size()&&hit<0;k++){if(k==next){depth++;next=nodes.size();cerr<<"depth "<<depth<<" labels "<<nodes.size()<<" retired "<<retired<<" comparisons "<<comparisons<<"\n";}if(!nodes[k].live)continue;int p=nodes[k].p;vector<int>r=nodes[k].r;for(int ei:inc[p]){auto&e=es[ei];vector<int>prev(d);for(int j=0;j<d;j++){long long x=(long long)e.in[j]+max(0,r[j]-e.out[j]);if(x>1000000){cout<<"status RESOURCE_LIMIT\n";return 0;}prev[j]=x;}add(e.from,prev,k,ei);if(nodes.size()>=limit){cout<<"status CAP labels "<<nodes.size()<<" depth "<<depth<<"\n";return 0;}if(hit>=0)break;}}
if(hit>=0){cout<<"status PETRI_WITNESS labels "<<nodes.size()<<" depth "<<depth<<"\n";vector<int>mark(d);int u=hit;cout<<"start "<<nodes[u].p<<"\n";while(nodes[u].parent>=0){auto&n=nodes[u];auto&e=es[n.edge];cout<<"EDGE "<<n.edge<<" "<<e.from<<" "<<e.to<<" "<<e.a;for(int x:mark)cout<<" "<<x;cout<<"\n";for(int j=0;j<d;j++){assert(mark[j]>=e.in[j]);mark[j]+=e.out[j]-e.in[j];}u=n.parent;}cout<<"goal "<<nodes[u].p;for(int x:mark)cout<<" "<<x;cout<<"\n";for(int j=0;j<d;j++)assert(mark[j]>=nodes[u].r[j]);}
else {cout<<"status EXHAUSTED_NO_ZERO_INITIAL labels "<<nodes.size()<<" live "<<nodes.size()-retired<<" depth "<<depth<<"\n";if(ac>3){ofstream o(av[3]);o<<d<<" "<<np<<" "<<nodes.size()-retired<<"\n";for(auto&n:nodes)if(n.live){o<<n.p;for(int x:n.r)o<<" "<<x;o<<"\n";}}} }
